// Fixed location: Agigea Sud / Agigea South Port, Constanța
const LAT = 44.1013;
const LON = 28.6145;

const form = $input.first().json;

const d1 = form['Calendar'] || form['Date'] || form['Data'] || form.date || form.date_1;
const d2 = form['Calendar 2'] || form['Date 2'] || form['Data 2'] || form.date_2 || null;

const hour = Math.max(0, Math.min(23, parseInt(form['Hour UTC'] ?? form['Hour'] ?? form.hour_utc ?? 8, 10)));
const shipHeading = form['Ship Heading'] || form['SHIP_HEADING'] || form.ship_heading || 'N/A';
const operationType = form['Operation Type'] || form.operation_type || 'cargo operation';

let documentId = form['Document ID'] || form.document_id || form.documentId || null;

// In the report workflow, inherit the Google Docs ID from the template copy.
if (!documentId) {
  try {
    const doc = $('Copy file').first().json;
    documentId = doc.id || doc.documentId || doc.document_id || doc.fileId || null;
  } catch (e) {
    documentId = null;
  }
}

if (!d1) {
  throw new Error('Data lipsește. Câmpuri primite: ' + JSON.stringify(Object.keys(form)));
}

// Do not fail here if documentId is missing; Update a document20 uses the copied Google Doc directly.
const dates = [{ slot: 1, date: String(d1).split('T')[0] }];
if (d2) dates.push({ slot: 2, date: String(d2).split('T')[0] });

return dates.map(d => ({
  json: {
    lat: LAT,
    lon: LON,
    slot: d.slot,
    date: d.date,
    hour,
    tip: operationType,
    ship_heading: shipHeading,
    document_id: documentId,
    iso: `${d.date}T${String(hour).padStart(2, '0')}:00:00Z`
  }
}));

const meta = $('Prepare Weather Request - Calendar').item.json;
const resp = $input.item.json;

const times = resp.hourly?.time || [];
const temps = resp.hourly?.temperature_2m || [];
const humidities = resp.hourly?.relative_humidity_2m || [];
const pressures = resp.hourly?.pressure_msl || [];
const windSpeeds = resp.hourly?.wind_speed_10m || [];
const windDirs = resp.hourly?.wind_direction_10m || [];
const windGusts = resp.hourly?.wind_gusts_10m || [];
const clouds = resp.hourly?.cloud_cover || [];
const visibilities = resp.hourly?.visibility || [];
const precipitations = resp.hourly?.precipitation || [];
const weatherCodes = resp.hourly?.weather_code || [];

const targetTime = `${meta.date}T${String(meta.hour).padStart(2, '0')}:00`;
const idx = times.findIndex(t => t === targetTime);

if (idx === -1) {
  throw new Error(`Nu s-au găsit date meteo pentru ${targetTime} UTC.`);
}

const compass = (deg) => {
  if (deg === null || deg === undefined) return 'N/A';
  return ['N','NNE','NE','ENE','E','ESE','SE','SSE','S','SSW','SW','WSW','W','WNW','NW','NNW'][Math.round(deg / 22.5) % 16];
};

const bft = (ms) => {
  if (ms === null || ms === undefined) return '?';
  const s = [0.3,1.5,3.4,5.4,7.9,10.7,13.8,17.1,20.7,24.4,28.4,32.6];
  for (let i = 0; i < s.length; i++) if (ms < s[i]) return i;
  return 12;
};

const weatherDesc = (code) => {
  const codes = {
    0: 'Clear sky', 1: 'Mainly clear', 2: 'Partly cloudy', 3: 'Overcast',
    45: 'Fog', 48: 'Depositing rime fog',
    51: 'Light drizzle', 53: 'Moderate drizzle', 55: 'Dense drizzle',
    56: 'Light freezing drizzle', 57: 'Dense freezing drizzle',
    61: 'Slight rain', 63: 'Moderate rain', 65: 'Heavy rain',
    66: 'Light freezing rain', 67: 'Heavy freezing rain',
    71: 'Slight snow fall', 73: 'Moderate snow fall', 75: 'Heavy snow fall',
    77: 'Snow grains',
    80: 'Slight rain showers', 81: 'Moderate rain showers', 82: 'Violent rain showers',
    85: 'Slight snow showers', 86: 'Heavy snow showers',
    95: 'Thunderstorm', 96: 'Thunderstorm with slight hail', 99: 'Thunderstorm with heavy hail'
  };
  return codes[code] || 'Unknown';
};

const formatDate = (isoDate) => {
  const d = new Date(`${isoDate}T00:00:00Z`);
  return d.toLocaleDateString('en-GB', {
    day: '2-digit',
    month: 'long',
    year: 'numeric',
    timeZone: 'UTC'
  });
};

const temp = temps[idx];
const hum = humidities[idx];
const press = pressures[idx];
const ws = windSpeeds[idx];
const wd = windDirs[idx];
const wg = windGusts[idx];
const cloud = clouds[idx];
const vis = visibilities[idx];
const rain = precipitations[idx];
const code = weatherCodes[idx];

const windKn = ws !== null && ws !== undefined ? Math.round(ws * 1.944 * 10) / 10 : null;
const gustKn = wg !== null && wg !== undefined ? Math.round(wg * 1.944 * 10) / 10 : null;
const visKm = vis !== null && vis !== undefined ? (vis / 1000).toFixed(1) + ' km' : 'N/A';

const weatherText =
`${weatherDesc(code)}, wind ${compass(wd)} ${bft(ws)} Bft` +
`${windKn !== null ? ` (${windKn} kn)` : ''}` +
`${gustKn !== null && gustKn > 0 ? `, gusts ${gustKn} kn` : ''}` +
`${temp !== null && temp !== undefined ? `, temperature ${temp}°C` : ''}` +
`${hum !== null && hum !== undefined ? `, humidity ${hum}%` : ''}` +
`${press !== null && press !== undefined ? `, pressure ${press} hPa` : ''}` +
`, visibility ${visKm}` +
`${cloud !== null && cloud !== undefined ? `, cloud cover ${cloud}%` : ''}` +
`${rain !== null && rain > 0 ? `, precipitation ${rain} mm/h` : ''}`;

return [{
  json: {
    slot: meta.slot,
    [`DATE_${meta.slot}`]: formatDate(meta.date),
    [`WEATHER_DATE${meta.slot}`]: weatherText,
    SHIP_HEADING: meta.ship_heading || 'N/A',
    reportText: `Weather conditions during ${meta.tip} at Agigea South Port — ${meta.date} ${String(meta.hour).padStart(2, '0')}:00 UTC\n${weatherText}\nSource: Open-Meteo Historical API / ERA5 reanalysis — Lat ${meta.lat}, Lon ${meta.lon}`,
    source: 'Open-Meteo Historical API / ERA5 reanalysis',
    lat: meta.lat,
    lon: meta.lon,
    document_id: meta.document_id
  }
}];

const items = $input.all().map(i => i.json);

const out = {
  DATE_1: 'N/A',
  WEATHER_DATE1: 'N/A',
  DATE_2: 'N/A',
  WEATHER_DATE2: 'N/A',
  SHIP_HEADING: 'N/A',
  reportText: '',
  document_id: items[0]?.document_id || null
};

if (!out.document_id) {
  throw new Error('Document ID missing after weather aggregation.');
}

for (const row of items) {
  if (row.DATE_1) out.DATE_1 = row.DATE_1;
  if (row.WEATHER_DATE1) out.WEATHER_DATE1 = row.WEATHER_DATE1;
  if (row.DATE_2) out.DATE_2 = row.DATE_2;
  if (row.WEATHER_DATE2) out.WEATHER_DATE2 = row.WEATHER_DATE2;
  if (row.SHIP_HEADING && row.SHIP_HEADING !== 'N/A') out.SHIP_HEADING = row.SHIP_HEADING;
}

out.reportText = [
  out.DATE_1 !== 'N/A' ? `${out.DATE_1}: ${out.WEATHER_DATE1}` : null,
  out.DATE_2 !== 'N/A' ? `${out.DATE_2}: ${out.WEATHER_DATE2}` : null,
  `Ship heading: ${out.SHIP_HEADING}`
].filter(Boolean).join('
');

return [{ json: out }];

const triggerData = $('Telegram Trigger').first().json;
const record = $input.first().json;

const rawText = triggerData.message.text.trim();

// Construiește filename curat
let filename = rawText.replace(/[^a-zA-Z0-9_\-]/g, '_');
filename = filename.replace(/_+/g, '_').replace(/^_|_$/g, '');

// Adaugă extensie dacă lipsește
if (!filename.match(/\.(png|jpg|jpeg|webp)$/i)) {
  filename += '.png';
}

return [{
  json: {
    filename,
    fileId: record.file_id,
    chatId: record.chat_id,
    recordId: record.id
  }
}];

const triggerData = $('Telegram Trigger2').first().json;
const record = $input.first().json;

const rawText = triggerData.message.text.trim();

// Construiește filename curat
let filename = rawText.replace(/[^a-zA-Z0-9_\-]/g, '_');
filename = filename.replace(/_+/g, '_').replace(/^_|_$/g, '');

// Adaugă extensie dacă lipsește
if (!filename.match(/\.(png|jpg|jpeg|webp)$/i)) {
  filename += '.png';
}

return [{
  json: {
    filename,
    fileId: record.file_id,
    chatId: record.chat_id,
    recordId: record.id
  }
}];
